//! The price table generated by `scripts/update-prices.py` (format in
//! `data/prices/README.md`), parsed once and looked up by provider, model and time.

use serde::Deserialize;
use std::collections::HashMap;
use thiserror::Error;

#[derive(Debug, Error)]
pub(crate) enum TableError {
    #[error("price table is not valid JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("price table schema {0} is not supported")]
    Schema(u32),
    #[error("price table has an invalid time: {0}")]
    Time(String),
    #[error("price table has an invalid price basis for {0}")]
    Basis(String),
}

/// US dollars per million tokens.
#[derive(Debug, Clone, Copy, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct TierRates {
    pub above: u64,
    pub input: Option<f64>,
    pub output: Option<f64>,
    pub cache_read: Option<f64>,
    pub cache_write: Option<f64>,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct Rates {
    pub input: f64,
    pub output: f64,
    pub cache_read: Option<f64>,
    pub cache_write: Option<f64>,
    #[serde(default)]
    pub tiers: Vec<TierRates>,
}

impl Rates {
    /// Listed with every rate at zero: free on that provider at that time.
    pub(crate) fn is_free(&self) -> bool {
        [
            Some(self.input),
            Some(self.output),
            self.cache_read,
            self.cache_write,
        ]
        .into_iter()
        .flatten()
        .all(|rate| rate == 0.0)
            && self.tiers.is_empty()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum StartBasis {
    ModelsDevCommit,
    Documented,
    FirstObserved,
}

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct PricePeriod {
    /// Epoch milliseconds; `None` for the first period, which also covers earlier calls.
    pub start_ms: Option<i64>,
    pub rates: Option<Rates>,
    pub basis: StartBasis,
    /// A source URL, or for models.dev periods the commit's URL.
    pub source: String,
}

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct ModelPrices {
    pub lab_equivalent: Option<(String, String)>,
    pub periods: Vec<PricePeriod>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) enum Billing {
    PerToken,
    Subscription,
}

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct BillingMode {
    pub provider: String,
    pub harness: Option<String>,
    pub price_provider: Option<String>,
    pub billing: Billing,
    pub valid_from_ms: Option<i64>,
    pub valid_until_ms: Option<i64>,
}

#[derive(Debug, Clone)]
pub(crate) struct PriceData {
    pub models_dev_commit: String,
    pub models_dev_committed_at: String,
    pub amendments_imported_from: Option<String>,
}

#[derive(Debug)]
pub(crate) struct PriceTable {
    pub data: PriceData,
    billing_modes: Vec<BillingMode>,
    providers: HashMap<String, HashMap<String, ModelPrices>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawTable {
    schema: u32,
    models_dev: RawModelsDev,
    amendments_imported_from: Option<RawImported>,
    billing_modes: Vec<RawBillingMode>,
    providers: HashMap<String, HashMap<String, RawModel>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawModelsDev {
    source: String,
    commit: String,
    committed_at: String,
}

#[derive(Deserialize)]
struct RawImported {
    commit: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawBillingMode {
    provider: String,
    harness: Option<String>,
    price_provider: Option<String>,
    billing: Billing,
    valid_from: Option<String>,
    valid_until: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct RawModel {
    lab_equivalent: Option<String>,
    prices: Vec<RawPeriod>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawPeriod {
    start: Option<String>,
    rates: Option<Rates>,
    commit: Option<String>,
    basis: Option<String>,
    source: Option<String>,
}

fn time_ms(value: &str) -> Result<i64, TableError> {
    chrono::DateTime::parse_from_rfc3339(value)
        .map(|time| time.timestamp_millis())
        .map_err(|_| TableError::Time(value.to_owned()))
}

fn optional_time_ms(value: Option<&str>) -> Result<Option<i64>, TableError> {
    value.map(time_ms).transpose()
}

fn split_key(value: &str) -> Option<(String, String)> {
    let (provider, model) = value.split_once('/')?;
    Some((provider.to_owned(), model.to_owned()))
}

impl PriceTable {
    pub(crate) fn parse(text: &str) -> Result<Self, TableError> {
        let raw: RawTable = serde_json::from_str(text)?;
        if raw.schema != 1 {
            return Err(TableError::Schema(raw.schema));
        }
        let commit_url = format!("{}/commit/", raw.models_dev.source);
        let mut providers = HashMap::with_capacity(raw.providers.len());
        for (provider, models) in raw.providers {
            let mut parsed = HashMap::with_capacity(models.len());
            for (model, raw_model) in models {
                let mut periods = Vec::with_capacity(raw_model.prices.len());
                for period in raw_model.prices {
                    let (basis, source) = match (period.basis.as_deref(), period.commit) {
                        (None, Some(commit)) => {
                            (StartBasis::ModelsDevCommit, format!("{commit_url}{commit}"))
                        }
                        (Some("documented"), _) => {
                            (StartBasis::Documented, period.source.unwrap_or_default())
                        }
                        (Some("firstObserved"), _) => {
                            (StartBasis::FirstObserved, period.source.unwrap_or_default())
                        }
                        _ => return Err(TableError::Basis(format!("{provider}/{model}"))),
                    };
                    periods.push(PricePeriod {
                        start_ms: optional_time_ms(period.start.as_deref())?,
                        rates: period.rates,
                        basis,
                        source,
                    });
                }
                parsed.insert(
                    model,
                    ModelPrices {
                        lab_equivalent: raw_model.lab_equivalent.as_deref().and_then(split_key),
                        periods,
                    },
                );
            }
            providers.insert(provider, parsed);
        }
        let billing_modes = raw
            .billing_modes
            .into_iter()
            .map(|mode| {
                Ok(BillingMode {
                    valid_from_ms: optional_time_ms(mode.valid_from.as_deref())?,
                    valid_until_ms: optional_time_ms(mode.valid_until.as_deref())?,
                    provider: mode.provider,
                    harness: mode.harness,
                    price_provider: mode.price_provider,
                    billing: mode.billing,
                })
            })
            .collect::<Result<_, TableError>>()?;
        Ok(Self {
            data: PriceData {
                models_dev_commit: raw.models_dev.commit,
                models_dev_committed_at: raw.models_dev.committed_at,
                amendments_imported_from: raw.amendments_imported_from.and_then(|item| item.commit),
            },
            billing_modes,
            providers,
        })
    }

    pub(crate) fn model(&self, provider: &str, model: &str) -> Option<&ModelPrices> {
        self.providers.get(provider)?.get(model)
    }

    /// The period in effect at `at_ms`. A call before the first recorded price uses it.
    pub(crate) fn period_at(
        &self,
        provider: &str,
        model: &str,
        at_ms: i64,
    ) -> Option<&PricePeriod> {
        let periods = &self.model(provider, model)?.periods;
        let later =
            periods.partition_point(|period| period.start_ms.is_none_or(|start| start <= at_ms));
        periods.get(later.saturating_sub(1))
    }

    /// The first billing mode matching the harness, provider and time.
    pub(crate) fn billing_mode(
        &self,
        harness: &str,
        provider: &str,
        at_ms: i64,
    ) -> Option<&BillingMode> {
        self.billing_modes.iter().find(|mode| {
            mode.provider == provider
                && mode
                    .harness
                    .as_deref()
                    .is_none_or(|expected| expected == harness)
                && mode.valid_from_ms.is_none_or(|start| start <= at_ms)
                && mode.valid_until_ms.is_none_or(|end| at_ms < end)
        })
    }
}
